@using sv_d872a55525d043e791154782d2ccbf60.Services

<nav class="settings-sidebar">
    <h3 class="sidebar-title">Settings</h3>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@using sv_d872a55525d043e791154782d2ccbf60.Services

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        <img src="@AvatarUrl" alt="Avatar" class="avatar-image" />
        <p class="avatar-url">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" class="form-control" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" class="form-control" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" @bind="Bio" class="form-control" rows="4"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="toast-message success">@_message</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string Bio { get; set; } = "";
    private string _message = "";

    private UserProfile? _lastSaved;

    protected override void OnParametersSet()
    {
        if (Profile is not null && _lastSaved != Profile)
        {
            _lastSaved = Profile;
            LoadFromProfile(Profile);
        }
    }

    private void LoadFromProfile(UserProfile profile)
    {
        DisplayName = profile.DisplayName;
        Email = profile.Email;
        AvatarUrl = profile.AvatarUrl;
        Bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _lastSaved = updated;
        _message = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        if (_lastSaved is not null)
        {
            LoadFromProfile(_lastSaved);
        }
        _message = "";
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = "";
        StateHasChanged();
    }
}

@using sv_d872a55525d043e791154782d2ccbf60.Services

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" @bind="EmailNotifications" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="PushNotifications" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" @bind="WeeklyDigest" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            <label class="channel-item">
                <input type="checkbox"
                       checked="@IsChannelMuted(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <span>#@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private List<string> AllChannels { get; set; } = new();

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            AllChannels = new List<string>(Prefs.MutedChannels);
            MutedChannels = new List<string>(Prefs.MutedChannels);
        }
    }

    private bool IsChannelMuted(string channel) => MutedChannels.Contains(channel);

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
    }
}

@using sv_d872a55525d043e791154782d2ccbf60.Services

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
        </button>

        @if (_passwordExpanded)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                </div>
